package mx.com.mesaregia.cotizaciones.integration.client;
import mx.com.mesaregia.cotizaciones.exception.*; import mx.com.mesaregia.cotizaciones.integration.dto.CoberturaPago; import org.springframework.stereotype.Component; import org.springframework.web.client.*; import java.math.BigDecimal;
@Component public class PagoCoverageRestAdapter implements PagoCoveragePort {private final RestClient client;public PagoCoverageRestAdapter(InternalRestClientFactory f){client=f.create(System.getenv().getOrDefault("MR_PAGOS_BASE_URL","http://localhost:8085"));}
 @Override public CoberturaPago consultar(Long c,Long v){try{var r=client.get().uri("/internal/v1/cuentas-cobro/cotizaciones/{c}/versiones/{v}",c,v).retrieve().body(CuentaDto.class);if(r==null)throw new BusinessRuleException("Cuenta de cobro no disponible");boolean cubierta=r.saldoParaConfirmar()!=null&&r.saldoParaConfirmar().compareTo(BigDecimal.ZERO)<=0;String ref=r.referenciaConfirmacion()!=null?r.referenciaConfirmacion():(r.idCuentaCobro()==null?null:"CTA-"+r.idCuentaCobro());return new CoberturaPago(cubierta,ref);}catch(HttpClientErrorException.NotFound e){throw new BusinessRuleException("No existe cuenta de cobro para la versión elegida");}catch(ResourceAccessException|HttpServerErrorException e){throw new IntegrationUnavailableException("mr-pagos-service no disponible");}}
 private record CuentaDto(Long idCuentaCobro,BigDecimal saldoParaConfirmar,String referenciaConfirmacion){}
}
